   222        for (ci = 0; ci < cinfo->comps_in_scan; ci++) {
   223          compptr = cinfo->cur_comp_info[ci];
   224          start_col = MCU_col_num * compptr->MCU_width;
   225          for (yindex = 0; yindex < compptr->MCU_height; yindex++) {
